 async function ensure(id,{variant='base',form,equipment:piece='original'}={}){if(!supports(id))return null;const m=form?manifest.forms[form]:manifest.bodies[id].variants[variant];if(!m||m.id!==id)throw Error('Unsupported recruit form');if(!form&&variant==='base')for(const fresh of [manifest.bodies[id].variants.fresh,manifest.bodies[id].variants.freshTruncheon])if(fresh)image(fresh).catch(e=>errors.set(fresh.atlas,String(e.message||e)));try{const im=await image(m);await equipment?.ensure(id,piece,m);errors.delete(m.atlas);return {...m,atlasImage:im,portrait:manifest.bodies[id].portrait};}catch(e){errors.set(m.atlas,String(e.message||e));throw e;}}
