 function frame(m,pose={}){const clip=m.clips[pose.clip]?pose.clip:'idle',frames=m.clips[clip];if(!frames)return null;const tick=pose.reduced?0:Number.isFinite(pose.frame)?Math.floor(pose.frame):Math.floor(Math.max(0,pose.elapsed||0)/m.frameMS[clip]),i=m.loop[clip]?((tick%6)+6)%6:Math.max(0,Math.min(5,tick)),index=frames[i];return {index,frame:i,clip,flip:pose.facing>0,drawn:true,provenance:'drawn-poses',playerArt:true,weapon:/truncheon/i.test(m.equipmentVariant)?'truncheon':'source-painted',sw:m.cellWidth,sh:m.cellHeight,sx:index%m.cols*m.cellWidth,sy:Math.floor(index/m.cols)*m.cellHeight};}
 function request(id,pose={}){const m=source(id,pose);if(m&&!cache.has(m.atlas)&&!pending.has(m.atlas)&&!errors.has(m.atlas))ensure(id,{variant:m.equipmentVariant,form:m.equipmentForm,equipment:pose.equipment||'original'}).catch(()=>{});}
 function draw(g,meta,pose={},x,y,height){let m=source(meta.id,pose);if(!m)return false;let v=touch(m.atlas);if(!v&&/^fresh/.test(m.equipmentVariant)){request(meta.id,pose);m=m.equipmentVariant==='freshTruncheon'&&manifest.bodies[meta.id].variants.truncheon||base(meta.id);v=touch(m.atlas);}if(!v){request(meta.id,pose);return false;}const f=frame(m,pose);if(!f)return false;const scale=m.renderHeight/m.visibleHeight*(height===undefined?1:height/base(meta.id).renderHeight)*(m.frameRenderScale?.[f.index]||1);if(!Number.isFinite(scale)||scale<=0||![x,y].every(Number.isFinite))return false;g.save();try{g.translate(x,y);if(f.flip)g.scale(-1,1);g.drawImage(v.image,f.sx,f.sy,f.sw,f.sh,-m.footX*scale,-m.footY*scale,f.sw*scale,f.sh*scale);const layer=equipment?.layer(meta.id,m,{...pose,clip:f.clip,equipment:pose.equipment||'original'},f);if(layer)g.drawImage(layer,-m.footX*scale,-m.footY*scale,f.sw*scale,f.sh*scale);f.equipment=pose.equipment||'original';f.equipmentReady=f.equipment==='original'||!!layer;draws++;}finally{g.restore();}return f;}
